'use server';
/**
 * @fileOverview Chatbot flow for EPIR Art Jewellery that provides a link to the consultation form when user expresses interest in a product or service.
 *
 * - chatBotPodajeLinkDoKonsultacji - A function that handles the chatbot interaction and provides a consultation link if the user is interested.
 * - ChatBotPodajeLinkDoKonsultacjiInput - The input type for the chatBotPodajeLinkDoKonsultacji function.
 * - ChatBotPodajeLinkDoKonsultacjiOutput - The return type for the chatBotPodajeLinkDoKonsultacji function.
 */

import {ai} from '@/ai/genkit';
import {z} from 'genkit';

const ChatBotPodajeLinkDoKonsultacjiInputSchema = z.object({
  userQuery: z.string().describe('The user query about EPIR Art Jewellery.'),
});
export type ChatBotPodajeLinkDoKonsultacjiInput = z.infer<typeof ChatBotPodajeLinkDoKonsultacjiInputSchema>;

const ChatBotPodajeLinkDoKonsultacjiOutputSchema = z.object({
  response: z.string().describe('The chatbot response to the user query, potentially including a link to the consultation form.'),
});
export type ChatBotPodajeLinkDoKonsultacjiOutput = z.infer<typeof ChatBotPodajeLinkDoKonsultacjiOutputSchema>;

export async function chatBotPodajeLinkDoKonsultacji(input: ChatBotPodajeLinkDoKonsultacjiInput): Promise<ChatBotPodajeLinkDoKonsultacjiOutput> {
  return chatBotPodajeLinkDoKonsultacjiFlow(input);
}

const prompt = ai.definePrompt({
  name: 'chatBotPodajeLinkDoKonsultacjiPrompt',
  input: {schema: ChatBotPodajeLinkDoKonsultacjiInputSchema},
  output: {schema: ChatBotPodajeLinkDoKonsultacjiOutputSchema},
  prompt: `Jesteś pomocnym asystentem EPIR Art Jewellery z Wrocławia. 
Prowadź naturalną rozmowę o biżuterii, materiałach, procesie tworzenia.
Zadawaj pytania o preferencje, styl, okazję. 
DOPIERO gdy klient wykaże konkretne zainteresowanie zamówieniem lub pyta "jak zamówić/kupić", 
wtedy zaproponuj formularz konsultacyjny: https://www.epir-art.com/konsultacja

Nie narzucaj formularza od razu. Najpierw poznaj potrzeby klienta.

User Query: {{{userQuery}}}
  `,
});

const chatBotPodajeLinkDoKonsultacjiFlow = ai.defineFlow(
  {
    name: 'chatBotPodajeLinkDoKonsultacjiFlow',
    inputSchema: ChatBotPodajeLinkDoKonsultacjiInputSchema,
    outputSchema: ChatBotPodajeLinkDoKonsultacjiOutputSchema,
  },
  async input => {
    const {output} = await prompt(input);
    return output!;
  }
);